BASE="""(a)=>{var [mode,cam,face]=a;var f=document.querySelector('#faces'),o=f.firstElementChild,n=o.cloneNode(true);n.classList.add('cur');o.classList.remove('cur');
 var fp=n.querySelector('.fp');fp.style.position='relative';
 [...n.querySelectorAll('*')].forEach(e=>{if(e.children.length===0&&/Rosto oval/.test(e.textContent))e.textContent='Não sei o meu';if(e.children.length===0&&/Armações de quase/.test(e.textContent))e.textContent='A câmera mede o seu rosto em menos de 1 minuto e mostra os modelos que combinam.';if(e.children.length===0&&/^Escolher$/.test(e.textContent.trim()))e.textContent='Abrir a câmera'});
 var h=[...n.querySelectorAll('*')].find(e=>e.children.length===0&&e.textContent==='Não sei o meu');
 if(mode=='C1')fp.innerHTML='<div style="position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(160deg,#f6eef4,#efe3ec);border-radius:22px"><div style="width:112px;height:112px;border-radius:50%;display:grid;place-items:center;background:#fff;color:#8d3a69;box-shadow:0 10px 26px rgba(80,20,60,.18)">'+cam.replace(/SZ/g,'50')+'</div></div>';
 if(mode=='C2'){n.style.setProperty('background','linear-gradient(150deg,#6e2457,#b0578e)','important');n.style.setProperty('border-color','transparent','important');fp.innerHTML='<div style="position:absolute;inset:0;display:grid;place-items:center;color:#fff">'+cam.replace(/SZ/g,'84')+'</div>';fp.style.setProperty('background','rgba(255,255,255,.12)','important');fp.style.borderRadius='22px';
   [...n.querySelectorAll('*')].forEach(e=>{if(e.children.length===0&&e.tagName!='svg')e.style.setProperty('color','#fff','important')});var bt=[...n.querySelectorAll('*')].find(e=>e.textContent.trim()==='Abrir a câmera'&&e.children.length===0);var B=bt.closest('span,div,b,button')||bt;var q=bt;while(q&&q!==n&&!(getComputedStyle(q).backgroundImage!='none'))q=q.parentElement;(q&&q!==n?q:bt).style.setProperty('background','#fff','important');bt.style.setProperty('color','#7b2d6b','important')}
 if(mode=='C3')fp.innerHTML='<div style="position:absolute;inset:0;display:grid;place-items:center">'+face+'</div><div style="position:absolute;right:10px;bottom:10px;width:48px;height:48px;border-radius:50%;display:grid;place-items:center;background:#8d3a69;color:#fff;box-shadow:0 6px 16px rgba(80,20,60,.3)">'+cam.replace(/SZ/g,'24')+'</div>';
 if(mode=='C4'){fp.innerHTML='<div style="position:absolute;inset:0;display:grid;place-items:center">'+face+'</div>';n.style.borderColor='#8d3a69';n.style.borderWidth='2px';n.insertAdjacentHTML('afterbegin','<span style="position:absolute;z-index:3;left:50%;top:-1px;transform:translate(-50%,-50%);background:#1d1d1f;color:#fff;font:800 11px Inter,sans-serif;letter-spacing:.14em;padding:6px 12px;border-radius:999px;white-space:nowrap">NOVO · COM CÂMERA</span>');n.style.position='relative';n.style.overflow='visible'}
 f.insertBefore(n,o);f.scrollLeft=0}"""
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/opt/pw-browsers/chromium',args=['--no-sandbox'])
    for m in ('C1','C2','C3','C4'):
        pg=b.new_page(viewport={'width':390,'height':844},device_scale_factor=2,is_mobile=True,has_touch=True,locale='pt-BR')
        pg.goto('http://localhost:8766/'); pg.wait_for_timeout(2500)
        pg.evaluate("document.querySelector('a[href=\"#rosto\"]').click()"); pg.wait_for_timeout(1800)
        pg.evaluate(BASE,[m,CAM,FACE]); pg.wait_for_timeout(700)
        pg.screenshot(path=f'r_{m}.png'); pg.close()
